I don't believe there is direct support for changing/setting the proxyName / proxyPort / etc. via YAML directly. I was able to accomplish this using WebServerFactoryCustomizer (org.springframework.boot.web.server) in a Configuration Bean. I haven't wired up Okta fully yet, but I can step through the setup and see that the Connector properties are being set.


YAML:


application:
  server:
    tomcat:
      proxy:
        name: mysite.mydomain.com
        port: 443
        scheme: https
        secure: true



Configuration Properties Object


@ConfigurationPropertiesScan
@ConfigurationProperties(prefix = "application.server.tomcat.proxy")
public class TomcatProxyConfiguration {


    private String name;
    private int port;
    private String scheme;
    private boolean secure;

    public String getName() {
        return name;
    }
    public void setName(String name) {
        this.name = name;
    }
    public int getPort() {
        return port;
    }
    public void setPort(int port) {
        this.port = port;
    }
    public String getScheme() {
        return scheme;
    }
    public void setScheme(String scheme) {
        this.scheme = scheme;
    }
    public boolean isSecure() {
        return secure;
    }
    public void setSecure(boolean secure) {
        this.secure = secure;
    }
}



Configuration Bean:


@Configuration
public class TomcatConfiguration {

    private TomcatProxyConfiguration tomcatProxyConfiguration;

    //pass in the Configuration Properties object via constructor injection
    public TomcatConfiguration(TomcatProxyConfiguration tomcatProxyConfiguration){
        this.tomcatProxyConfiguration = tomcatProxyConfiguration;
    }

    @Bean
    public WebServerFactoryCustomizer<TomcatServletWebServerFactory> tomcatCustomizer() {
        return factory -> factory.addConnectorCustomizers((Connector connector) -> {
            connector.setProxyName(tomcatProxyConfiguration.getName());
            connector.setProxyPort(tomcatProxyConfiguration.getPort());
            connector.setScheme(tomcatProxyConfiguration.getScheme());
            connector.setSecure(tomcatProxyConfiguration.isSecure());
        });
    }
}



