Based on my comment, you could probably write something like this as wel.


@Configuration
@Validated
@HttpServiceClientValidatingConfig.ValidateRequiredProperties
public class HttpServiceClientValidatingConfig {

  private final HttpServiceClientProperties props;

  HttpServiceClientValidatingConfig(HttpServiceClientProperties props) {
    this.props = props;
  }

  HttpServiceClientProperties getProps() {
    return props;
  }

  @Target({ElementType.TYPE})
  @Retention(RetentionPolicy.RUNTIME)
  @Constraint(validatedBy = ValidateRequiredPropertiesValidator.class)
  @Documented
  public static @interface ValidateRequiredProperties {
    String message() default "{jakarta.validation.constraints.NotBlank.message}";
    Class<?>[] groups() default {};
    Class<? extends Payload>[] payload() default {};
  }

  public static class ValidateRequiredPropertiesValidator
      implements ConstraintValidator<ValidateRequiredProperties, HttpServiceClientValidatingConfig> {

    private String message;

    @Override
    public void initialize(ValidateRequiredProperties ca) {
      this.message = ca.message();
    }

    @Override
    public boolean isValid(HttpServiceClientValidatingConfig httpServiceClientValidatingConfig, ConstraintValidatorContext ctx) {
      var props = httpServiceClientValidatingConfig.getProps();
      var valid = true;
      for (var prop : props.entrySet()) {
        var name = prop.getKey();
        var value = prop.getValue();
        var url = value.getBaseUrl();
        if (ObjectUtils.isEmpty(url)) {
          valid = false;
          ctx.buildConstraintViolationWithTemplate(this.message)
              .addPropertyNode("spring.http.service-client." + name + ".base-url")
              .addConstraintViolation().disableDefaultConstraintViolation();
        }
      }
      return valid;
    }
  }
}



