It seems like what you are trying to write is the 
lazy { ... }
 property delegate, but also allowing manually setting a different initial value. You can write this as a property delegate too. (Adapted from 
Lazy.kt
)


class MutableLazy<T>(initializer: () -> T) : Lazy<T> {
    private object UNINITIALIZED_VALUE
    private var initializer: (() -> T)? = initializer
    private var _value: Any? = UNINITIALIZED_VALUE

    override var value: T
        get() {
            if (_value === UNINITIALIZED_VALUE) {
                _value = initializer!!()
                initializer = null
            }
            @Suppress("UNCHECKED_CAST")
            return _value as T
        }
        set(value) {
            if(_value !== UNINITIALIZED_VALUE) {
                throw IllegalStateException()
            }
            _value = value
            initializer = null
        }

    override fun isInitialized(): Boolean = _value !== UNINITIALIZED_VALUE

    override fun toString(): String = if (isInitialized()) value.toString() else "Lazy value not initialized yet."

    operator fun setValue(thisRef: Any?, property: KProperty<*>, value: T) {
        _value = value
    }
}

fun <T> mutableLazy(initializer: () -> T): MutableLazy<T> = MutableLazy(initializer)



