from datetime import datetime, date

def do_sort(d:dict[str, list[date]]) -> list[tuple[str, date]]:
    combo = []
    for k, v in d.items():
        for e in v:
            combo.append((k, e))
    return sorted(combo, key=lambda e: (e[1], e[0]))

