You can register a custom 
deserialization modifier
 with a custom 
EnumDeserializer
 that maps names in the way you want.


You can do that by calling the 
setDeserializerModifier
 on your 
Module
 and override the 
modifyEnumDeserializer
 method in the (
BeanDeserializerModifier
) parameter allowing you to return a custom 
JsonDeserializer
 for enums. There, you can return a custom 
JsonDeserializer
. To also use it with 
Map
 keys, you also need a custom 
KeyDeserializer


ObjectMapper mapper = new ObjectMapper()
    .registerModule(
            new SimpleModule()
                // your code, nothing new
                .addSerializer(Enum.class, new JsonSerializer<Enum>() {
                    @Override
                    public void serialize(Enum value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
                        gen.writeString(reverseString(value.name()));
                    }
                })
                .addKeySerializer(Enum.class, new JsonSerializer<Enum>() {
                    @Override
                    public void serialize(Enum value, JsonGenerator gen, SerializerProvider serializers) throws IOException {
                        gen.writeFieldName(reverseString(value.name()));
                    }
                })
                // create a deserialization modifier for your custom names
                .setDeserializerModifier(new BeanDeserializerModifier() {
                    @Override
                    public JsonDeserializer<?> modifyEnumDeserializer(DeserializationConfig config, JavaType type, BeanDescription beanDesc, JsonDeserializer<?> deserializer) {
                        return new CustomEnumDeserializer<>(type);
                    }

                    @Override
                    public KeyDeserializer modifyKeyDeserializer(DeserializationConfig config, JavaType type, KeyDeserializer deserializer) {
                        if(type.isEnumType()){
                            return new CustomEnumKeyDeserializer<>(type));
                        }
                        return deserializer;
                    }
                })
    );



Deserializer classes:


class CustomEnumDeserializer<T extends Enum<T>> extends JsonDeserializer<T> {
    private final Class<T> enumClass;

    CustomEnumDeserializer(JavaType type) {
        this.enumClass = (Class<T>) type.getRawClass();
    }

    @Override
    public Enum<T> deserialize(JsonParser p, DeserializationContext ctxt) throws IOException, JacksonException {
        // deserialize the enum how you want to
        return Enum.valueOf(enumClass, reverseString(p.getText()));
    }
}

class CustomEnumKeyDeserializer<T extends Enum<T>> extends KeyDeserializer {
    private final Class<T> enumClass;

    CustomEnumKeyDeserializer(JavaType type) {
        this.enumClass = (Class<T>) type.getRawClass();
    }

    @Override
    public Object deserializeKey(String key, DeserializationContext ctxt) throws IOException {
        return Enum.valueOf(enumClass, reverseString(key));
    }
}

