JavaScript






// Helper function
function* takeWhile(iter, predicate) {
    for (const value of iter) {
        if (!predicate(value)) break;
        yield value;
    }
}

// Shell sort now takes a gap sequence as second argument
function shellSort(arr, gapSequence) {
    const n = arr.length;
    // Collect gaps <= n
    const gaps = [...takeWhile(gapSequence, g => g < n)];

    // Iterate gaps in reverse order
    gaps.reverse();

    for (const gap of gaps) {
        for (let i = gap; i < n; i++) {
            const temp = arr[i];
            let j = i;
            while (j >= gap && arr[j - gap] > temp) {
                arr[j] = arr[j - gap];
                j -= gap;
            }
            arr[j] = temp;
        }
    }
}

// Example gap sequence: this is Sedgewick, 1986, sequence https://oeis.org/A033622
function* sedgewickSequence() {
    for (let i = 0; true; i++) {
        yield 1 + ((9 - i % 2) << i) - (((3 - i % 2) * 3) << ((i + 1) / 2));
    }
}

// main
const arr = [23, 12, 1, 8, 34, 54, 2, 3, 18, 22, 6, 36, 7, 0, 27, 30, 11, 19, 14, 9];

shellSort(arr, sedgewickSequence());

console.log(...arr);








Python


from itertools import takewhile, count

# Shell sort now takes a gap sequence as second argument
def shell_sort(lst, gap_sequence):
    n = len(lst)
    # Collect gaps <= n
    gaps = list(takewhile(lambda g: g < n, gap_sequence))

    # Iterate gaps in reverse order
    gaps.reverse()

    for gap in gaps:
        for i in range(gap, n):
            temp = lst[i]
            for j in range(i, gap-1, -gap):
                if lst[j - gap] <= temp:
                    break
                lst[j], lst[j - gap] = lst[j - gap], temp

# Example gap sequence: this is Sedgewick, 1986, sequence https://oeis.org/A033622
def sedgewick_sequence():
    for i in count(0):
        yield 1 + ((9 - i % 2) << i) - (((3 - i % 2) * 3) << ((i + 1) // 2))

# main
lst = [23, 12, 1, 8, 34, 54, 2, 3, 18, 22, 6, 36, 7, 0, 27, 30, 11, 19, 14, 9]

shell_sort(lst, sedgewick_sequence())

print(*lst)

There is no helper function in 
CompletableFuture
 that returns 
first future to complete with a non-null value
.


You can implement your own:


public static <T> CompletableFuture<T> anyNotNull(Collection<CompletableFuture<? extends T>> cfs) {
    var cfsCopy = new ArrayList<>(cfs);

    if (cfsCopy.isEmpty()) {
        return CompletableFuture.failedFuture(new NoSuchElementException("No futures provided"));
    }

    var result = new CompletableFuture<T>();
    var remaining = new AtomicInteger(cfsCopy.size());

    for (CompletableFuture<? extends T> cf : cfsCopy) {
        cf.whenComplete((v, ex) -> {
            if (Objects.nonNull(v)) {
                result.complete(v);
                return;
            }
            if (remaining.decrementAndGet() == 0) {
                result.completeExceptionally(new NoSuchElementException("No future completed with a non-null value"));
            }
        });
    }

    return result;
}



Few notes about the code:




make a copy of the input collection to avoid issues if the caller mutates the list of passed futures


return a failed future if:



the collection is empty


all futures complete with null or exceptionally








Possible changes of the code that could make sense. Some of them are inspired by implementation of 
CompletableFuture.anyOf
:




check for already completed futures with non-null results before attaching callbacks via 
whenComplete


cancel remaining futures once an acceptable result is found


accept 
varargs
 instead of a 
Collection
 parameter


log exceptions from futures that complete exceptionally instead of ignoring them

