import java.net.URLEncoder;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Properties;

public class JDBCSelect {

    public static void main(String[] args){
        try {
            //===============================================
            // Connecting to a cluster
            //===============================================
            // Connection information of JDBC
            String jdbcAddress = "127.0.0.2";
            String jdbcPort = "20001";
            String clusterName = "cluster1";
            String databaseName = "public";
            String username = "admin";
            String password = "admin";
            String applicationName = "SampleJDBC";

            // Encoding a cluster name and a database name
            String encodeClusterName = URLEncoder.encode(clusterName, "UTF-8");
            String encodeDatabaseName = URLEncoder.encode(databaseName, "UTF-8");
            String encodeNotificationMember = URLEncoder.encode(jdbcAddress +":"+jdbcPort, "UTF-8");

            // Creating a URL (Multicast method)
            //String jdbcUrl = "jdbc:gs://"+jdbcAddress+":"+jdbcPort+"/"+encodeClusterName+"/"+encodeDatabaseName;
             // Creating a URL (FIXED_LIST method)
             String jdbcUrl = "jdbc:gs:///"+encodeClusterName+"/"+encodeDatabaseName+"?notificationMember="+encodeNotificationMember;

            Properties prop = new Properties();
            prop.setProperty("user", username);
            prop.setProperty("password", password);
            prop.setProperty("applicationName", applicationName);

            // Connecting
            Connection con = DriverManager.getConnection(jdbcUrl, prop);

            //===============================================
            // Creating a container and registering data
            //===============================================
            {
                Statement stmt = con.createStatement();

                // (Delete the container if it already exists)
                stmt.executeUpdate("DROP TABLE IF EXISTS SampleJDBC_Select");

                // Creating a container
                stmt.executeUpdate("CREATE TABLE IF NOT EXISTS SampleJDBC_Select ( id integer PRIMARY KEY, value string )");
                System.out.println("SQL Create Table name=SampleJDBC_Select");

                // Registering a row
                int ret1 = stmt.executeUpdate("INSERT INTO SampleJDBC_Select values "+
                                            "(0, 'test0'),(1, 'test1'),(2, 'test2'),(3, 'test3'),(4, 'test4')");
                System.out.println("SQL Insert count=" + ret1);

                stmt.close();
            }

            //===============================================
            // Executing a search
            //===============================================
            // (1) Creating a statement
            Statement stmt = con.createStatement();

            // (2) Executing a SQL command
            ResultSet rs = stmt.executeQuery("SELECT * from SampleJDBC_Select where ID > 2");

            // (3) Getting a result
            while( rs.next() ){
                int id = rs.getInt(1);
                String value = rs.getString(2);
                System.out.println("SQL row(id=" + id + ", value=" + value + ")");
            }

            //===============================================
            // Terminating process
            //===============================================
            stmt.close();
            con.close();
            System.out.println("success!");

        } catch ( Exception e ){
            e.printStackTrace();
        }
    }
}

If you want to embed some XML fragments into the generated document, I don't think that high-level XML mappers are the right tool. I would use a more manual approach. Here is a solution based on the 
XOM
 library.


Assuming you have this class:


public class MetaInfo
{
    private String id;
    private String name;
    private String description;

    public String getId()
    {
        return id;
    }

    public void setId(String id)
    {
        this.id = id;
    }

    public String getName()
    {
        return name;
    }

    public void setName(String name)
    {
        this.name = name;
    }

    public String getDescription()
    {
        return description;
    }

    public void setDescription(String description)
    {
        this.description = description;
    }
}



You can generate the MetaInfo file like this:


import java.io.*;
import nu.xom.*;

class MetaInfoGenerator
{
    private void addSimpleValue(Element parent, String name, String value)
    {
        Element element = new Element(name);
        element.appendChild(value);
        parent.appendChild(element);
    }

    private void addXmlValue(Element parent, String name, String value) throws ParsingException, IOException
    {
        String xml = String.format("<%s>%s</%s>", name, value, name);
        Document doc = new Builder().build(xml, null);
        parent.appendChild(doc.getRootElement().copy());
    }

    public void createMetaInfo(MetaInfo metaInfo, OutputStream out) throws ParsingException, IOException
    {
        Element root = new Element("component");
        root.addAttribute(new Attribute("type", "desktop-application"));
        addSimpleValue(root, "id", metaInfo.getId());
        addSimpleValue(root, "name", metaInfo.getName());
        addXmlValue(root, "description", metaInfo.getDescription());

        Document doc = new Document(root);
        Serializer serializer = new Serializer(out, "UTF-8");
        serializer.setIndent(4);
        serializer.write(doc);
    }

    public static void main(String[] args) throws ParsingException, IOException
    {
        MetaInfo metaInfo = new MetaInfo();
        metaInfo.setId("com.example.foobar");
        metaInfo.setName("Foo Bar");
        metaInfo.setDescription("<p>An awesome app!</p>");

        new MetaInfoGenerator().createMetaInfo(metaInfo, System.out);
    }
}



