The response from


/weatherapi/locationforecast/2.0/compact



may not always be a 200 OK so you want to give a more transparent response. Try this instead


public ResponseEntity<Forecast> getLocationForecast(double latitude, double longitude) {

    Response response1 = client.target("/weatherapi/locationforecast/2.0/compact")
            .queryParam("lat", latitude)
            .queryParam("lon", longitude)
            .request(MediaType.APPLICATION_JSON_VALUE)
            .get();

    MetResponse mr = response1.readEntity(MetResponse.class);
    assert mr != null;
    Forecast f = Forecast.fromMetResponse(mr);

    ResponseEntity<Forecast> responseEntity = ResponseEntity
            .status(response1.getStatus())
            .header("h1", response1.getHeaderString("h1"))
            .header("h2", response1.getHeaderString("h2"))
            .header("h3", response1.getHeaderString("h3"))
            .header("h4", response1.getHeaderString("h4"))
            .contentType(MediaType.APPLICATION_JSON)
            .body(f);

    return responseEntity;
}



