    import org.springframework.jms.core.JmsTemplate;
    import org.springframework.stereotype.Component;

    @Component
    public class MessageProducer {

        private final JmsTemplate jmsTemplate;

        public MessageProducer(JmsTemplate jmsTemplate) {
            this.jmsTemplate = jmsTemplate;
        }

        public void sendMessage(String type, SomeDto someDto) {
            jmsTemplate.convertAndSend(
                    "test_queue",
                    someDto,
                    message -> {
                        message.setStringProperty("my_message_type", type); // typeA, typeB
                        // message.setJMSCorrelationID(type);
                        return message;
                    }
            );
        }
    }



Also as you can see in the code sample above, you could also use correlation id instead of setting 
my_message_type
