In your aspect, you need to exclude both interface types by 
!is(InterfaceType))
 and the aspect itself by 
!within(MyAspect)
 to avoid the aspect trying to weave into its own static initialiser, which would lead to a runtime error during aspect bootstrapping.


package de.scrum_master.stackoverflow.q79557444.aspect;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;

@Aspect
public class MyAspect {
  @Around("staticinitialization(!is(InterfaceType)) && !within(MyAspect)")
  public Object myAdvice(ProceedingJoinPoint joinPoint) throws Throwable {
    System.out.println(joinPoint);
    return joinPoint.proceed();
  }
}



