StringCopy.java


The different approaches used to extract strings out of a 
MemorySegment
 into a 
String
.


package com.example;

import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import jdk.internal.access.JavaLangAccess;
import jdk.internal.access.SharedSecrets;

public sealed interface StringCopy {

  String copy(MemorySegment segment, Charset charset);

  private static int nullCharLength(Charset charset) {
    if (charset == StandardCharsets.UTF_32) return 4;
    else if (charset == StandardCharsets.UTF_16) return 2;
    else return 1;
  }

  final class Direct implements StringCopy {

    @Override
    public String copy(MemorySegment segment, Charset charset) {
      return segment.getString(0L, charset);
    }
  }

  final class Manual implements StringCopy {

    @Override
    public String copy(MemorySegment segment, Charset charset) {
      int length = (int) (segment.byteSize() - nullCharLength(charset));

      byte[] bytes = new byte[length];
      MemorySegment.copy(segment, ValueLayout.JAVA_BYTE, 0L, bytes, 0, length);
      return new String(bytes, charset);
    }
  }

  final class Access implements StringCopy {

    private static final JavaLangAccess JLA = SharedSecrets.getJavaLangAccess();

    @Override
    public String copy(MemorySegment segment, Charset charset) {
      int length = (int) (segment.byteSize() - nullCharLength(charset));

      byte[] bytes = new byte[length];
      MemorySegment.copy(segment, ValueLayout.JAVA_BYTE, 0L, bytes, 0, length);
      try {
        return JLA.newStringNoRepl(bytes, charset);
      } catch (CharacterCodingException ex) {
        throw new RuntimeException(ex);
      }
    }
  }

  final class Decoder implements StringCopy {

    @Override
    public String copy(MemorySegment segment, Charset charset) {
      var buffer = segment.asByteBuffer();
      buffer.limit(buffer.limit() - nullCharLength(charset));

      return charset.decode(buffer).toString();
    }
  }
}



StringCopyBenchmarks.java


package com.example;

import java.lang.foreign.Arena;
import java.lang.foreign.MemorySegment;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.TearDown;

@Fork(1)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Measurement(iterations = 10, time = 15, timeUnit = TimeUnit.SECONDS)
@State(Scope.Benchmark)
public class StringCopyBenchmarks {

  @Param private Encoding encoding;
  @Param private Type type;
  @Param private Text text;
  private StringCopy strcpy;

  private Arena arena;
  private MemorySegment segment;

  @Setup
  public void setup() {
    strcpy = type.createStringCopyInstance();
    arena = Arena.ofConfined();
    segment = arena.allocateFrom(text.text(), encoding.charset());
  }

  @TearDown
  public void tearDown() {
    arena.close();
  }

  @Benchmark
  public String copy() {
    return strcpy.copy(segment, encoding.charset());
  }

  public enum Type {
    DIRECT(StringCopy.Direct.class),
    MANUAL(StringCopy.Manual.class),
    ACCESS(StringCopy.Access.class),
    DECODER(StringCopy.Decoder.class);

    private final Class<? extends StringCopy> cls;

    Type(Class<? extends StringCopy> cls) {
      this.cls = cls;
    }

    StringCopy createStringCopyInstance() {
      try {
        return cls.getConstructor().newInstance();
      } catch (ReflectiveOperationException ex) {
        throw new RuntimeException(ex);
      }
    }
  }

  public enum Encoding {
    US_ASCII(StandardCharsets.US_ASCII),
    ISO_8859_1(StandardCharsets.ISO_8859_1),
    UTF_8(StandardCharsets.UTF_8),
    UTF_16(StandardCharsets.UTF_16),
    UTF_32(StandardCharsets.UTF_32);

    private final Charset charset;

    Encoding(Charset charset) {
      this.charset = charset;
    }

    Charset charset() {
      return charset;
    }
  }

  public enum Text {
    LATIN(TestStrings.LATIN_TEXT),
    UNICODE(TestStrings.UNICODE_TEXT);

    private final String text;

    Text(String text) {
      this.text = text;
    }

    String text() {
      return text;
    }
  }
}



