import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import io.github.bonigarcia.wdm.WebDriverManager;

import java.time.Duration;

public class TransatSearchAutomation {
    public static void main(String[] args) {
        // Setup ChromeDriver using WebDriverManager
        WebDriverManager.chromedriver().setup();

        // Set ChromeOptions
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--start-maximized");
        options.addArguments("--disable-notifications");
        options.addArguments("--disable-popup-blocking");
        options.setExperimentalOption("excludeSwitches", new String[]{"enable-automation"});
        options.setExperimentalOption("useAutomationExtension", false);

        // Initialize WebDriver
        WebDriver driver = new ChromeDriver(options);
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(5));

        try {
            // Open the website
            driver.get("https://www.transat.com/fr-CA?search=package");

            // Wait for 'FROMSEARCH' element and click
            WebElement fromSearch = wait.until(ExpectedConditions.presenceOfElementLocated(By.id("FROMSEARCH")));
            fromSearch.click();
            Thread.sleep(2000);

            // Select departure city
            WebElement departureCity = driver.findElement(By.cssSelector("#YUL-FROMSEARCH > span.code"));
            departureCity.click();

            // Wait for 'TOSEARCH' element and click
            WebElement toSearch = wait.until(ExpectedConditions.presenceOfElementLocated(By.id("TOSEARCH")));
            toSearch.click();
            Thread.sleep(2000);

            // Select destination city
            WebElement destinationCity = driver.findElement(By.cssSelector("#City-13-TOSEARCH > div > span.name"));
            destinationCity.click();
            Thread.sleep(2000);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            // Close the browser
            driver.quit();
        }
    }
}

I found a working solution. Liberty 23.x does not expose TransactionManager over JNDI, you need to use reflection to obtain TransactionManager.


This bean definition helped me configure JtaTransactionManager.


    @Bean
    public JtaTransactionManager transactionManager() throws Exception {
        InitialContext context = new InitialContext();

        UserTransaction utx = (UserTransaction) context.lookup("java:comp/UserTransaction");

        TransactionManager ibmTm = (TransactionManager) Class
            .forName("com.ibm.tx.jta.TransactionManagerFactory")
            .getDeclaredMethod("getTransactionManager")
            .invoke(null);

        return new JtaTransactionManager(utx, ibmTm);
    }



