        humanPoints.setText(model.getHumanTilesDisplay());
        humanPoints.setForeground(Color.BLUE);
        humanPoints.setFont(new Font("Verdana", Font.BOLD, 20));
        panel.add(humanPoints);

        // Just a test button, that creates a random combination of tiles
        // To test, if the labels update correctly.
        JButton testButton = new JButton("Test");
        testButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent event) {
                Dimension d = model.getBoardSize();
                int randomXPieces = random.nextInt(8) + 3;
                model.setHumanTiles(randomXPieces);
                for (int i = 0; i < randomXPieces; i++) {
                    int row = random.nextInt(d.height);
                    int col = random.nextInt(d.width);
                    model.setBoardCell(row, col, "X");
                }

                int randomOPieces = random.nextInt(8) + 3;
                model.setMachineTiles(randomOPieces);
                for (int i = 0; i < randomOPieces; i++) {
                    int row = random.nextInt(d.height);
                    int col = random.nextInt(d.width);
                    model.setBoardCell(row, col, "O");
                }

                updateButtonPanel();
                drawingPanel.repaint();
            }
        });
        panel.add(testButton);

        label = new JLabel("Machine Tiles:");
        panel.add(label);

        // Label for a number of machine's tiles
        machinePoints = new JLabel();
        machinePoints.setText(model.getMachineTilesDisplay());
        machinePoints.setForeground(Color.RED);
        machinePoints.setFont(new Font("Verdana", Font.BOLD, 20));
        panel.add(machinePoints);

        return panel;
    }

    public void updateButtonPanel() {
        humanPoints.setText(model.getHumanTilesDisplay());
        machinePoints.setText(model.getMachineTilesDisplay());
    }

    public void repaintDrawingPanel() {
        drawingPanel.repaint();
    }

    public class DrawingPanel extends JPanel {

        private static final long serialVersionUID = 1L;

        private final int border, cellWidth, diameter, padding;

        private final ReversiExampleModel model;

        public DrawingPanel(ReversiExample view, ReversiExampleModel model) {
            this.model = model;
            this.cellWidth = model.getCellWidth();
            this.diameter = (int) Math.round(cellWidth * 0.85);
            this.padding = (int) Math.round(cellWidth * 0.05);
            this.border = model.getBorder();
            Dimension d = model.getBoardSize();
            int width = d.width * cellWidth + border + border;
            int height = d.height * cellWidth + border + border;
            this.setPreferredSize(new Dimension(width, height));
            this.addMouseListener(new BoardListener(view, model));
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            g.setColor(Color.BLACK);
            g.fillRect(0, 0, this.getWidth(), this.getHeight());

            // Prints the tiles, according to the value of each tile
            Dimension d = model.getBoardSize();
            for (int row = 0; row < d.height; row++) {
                int y = row * cellWidth + border;
                for (int col = 0; col < d.width; col++) {
                    int x = col * cellWidth + border;
                    drawCells(g, y, x);
                    drawPieces(g, row, y, col, x);
                }
            }

        }

        private void drawCells(Graphics g, int y, int x) {
            g.setColor(Color.GREEN);
            g.fillRect(x, y, cellWidth, cellWidth);
            g.setColor(Color.BLACK);
            g.drawRect(x, y, cellWidth, cellWidth);
        }

        private void drawPieces(Graphics g, int row, int y, int col, int x) {
            switch (model.getBoardCell(row, col)) {
            case "X":
                g.setColor(Color.BLUE);
                g.fillOval(x + padding, y + padding, diameter, diameter);
                g.setColor(Color.BLACK);
                g.drawOval(x + padding, y + padding, diameter, diameter);
                break;
            case "O":
                g.setColor(Color.RED);
                g.fillOval(x + padding, y + padding, diameter, diameter);
                g.setColor(Color.BLACK);
                g.drawOval(x + padding, y + padding, diameter, diameter);
                break;
            default:
                break;
            }
        }

    }

    public class BoardListener extends MouseAdapter {

        private final ReversiExample view;

        private final ReversiExampleModel model;

        public BoardListener(ReversiExample view, ReversiExampleModel model) {
            this.view = view;
            this.model = model;
        }

        @Override
        public void mousePressed(MouseEvent event) {
            Point p = event.getPoint();
            int border = model.getBorder();
            int cellWidth = model.getCellWidth();
            int row = (p.y - border) / cellWidth;
            int col = (p.x - border) / cellWidth;
            String value = model.getBoardCell(row, col);
            if (value.equals(" ")) {
                model.addPiece(row, col);
            } else {
                model.reverseColor(row, col);
            }

            model.nextTurn();
            view.updateButtonPanel();
            view.repaintDrawingPanel();
        }

    }

    public class ReversiExampleModel {

        private boolean playersTurn;

        private int humanTiles, machineTiles;
        private final int border, cellWidth;

        private final Dimension boardSize;

        private String[][] board;

        public ReversiExampleModel() {
            this.boardSize = new Dimension(8, 8);
            this.board = new String[boardSize.height][boardSize.width];
            this.humanTiles = 0;
            this.machineTiles = 0;
            this.border = 10;
            this.cellWidth = 60;
            this.playersTurn = true;

            for (int row = 0; row < boardSize.height; row++) {
                for (int col = 0; col < boardSize.width; col++) {
                    board[row][col] = " ";
                }
            }
        }

        public Dimension getBoardSize() {
            return boardSize;
        }

        public void setBoardCell(int row, int col, String value) {
            this.board[row][col] = value;
        }

        public String getBoardCell(int row, int col) {
            return board[row][col];
        }

        public void addPiece(int row, int col) {
            if (playersTurn) {
                board[row][col] = "X";
                humanTiles++;
            } else {
                board[row][col] = "O";
                machineTiles++;
            }
        }

        public void reverseColor(int row, int col) {
            if (board[row][col].equals("X")) {
                board[row][col] = "O";
                humanTiles--;
                machineTiles++;
            } else if (board[row][col].equals("O")) {
                board[row][col] = "X";
                humanTiles++;
                machineTiles--;
            }
        }

        public void setHumanTiles(int humanTiles) {
            this.humanTiles = humanTiles;
        }

        public void setMachineTiles(int machineTiles) {
            this.machineTiles = machineTiles;
        }

        public void incrementHumanTiles(int increment) {
            this.humanTiles += increment;
        }

        public void incrementMachineTiles(int increment) {
            this.machineTiles += increment;
        }

        public String getHumanTilesDisplay() {
            return Integer.toString(humanTiles);
        }

        public String getMachineTilesDisplay() {
            return Integer.toString(machineTiles);
        }

        public int getBorder() {
            return border;
        }

        public int getCellWidth() {
            return cellWidth;
        }

        public boolean isPlayersTurn() {
            return playersTurn;
        }

        public void nextTurn() {
            this.playersTurn = !this.playersTurn;
        }

    }

}

Since your enum constants are provided with an argument, I assume you omitted a 
String
 field and a one-arg constructor in the definition of 
HandDrive
 when you posted your question.


By default, Jackson serializes enum values with the name of the corresponding constant. This is why the JSON produced contains 
RIGHT
 or 
LEFT
. If you want to serialize an enum with one of its fields, you could either use the annotation 
@JsonValue
 or a custom serializer.


@JsonValue Approach


By using 
@JsonValue
, you do not need XML annotations anymore. In fact, this annotation works for both JSON and XML serializations. To use it, just annotate the field 
value
 or its getter 
getValue()
 with it. Here is a demo at 
OneCompiler
.


enum HandDrive {
    RIGHT("right"),
    LEFT("left");

    @JsonValue
    private String value;

    HandDrive(String value) {
        this.value = value;
    }

    // Alternatively here
    // @JsonValue
    public String getValue() {
        return value;
    }
}



Custom Serializer Approach for Specific Enum


If you do not want to use any annotation, you could define a custom serializer for the enum 
HandDrive
, and then register it as a module on both 
ObjectMapper
 and 
XmlMapper
. Here is a demo at 
OneCompiler
.


class HardDriveSerializer extends StdSerializer<HandDrive> {

    public HardDriveSerializer(){
        this(null);
    }

    public HardDriveSerializer(Class<HandDrive> t) {
        super(t);
    }

    @Override
    public void serialize(HandDrive value, JsonGenerator gen, SerializerProvider provider) throws IOException {
        gen.writeString(value.getValue());
    }
}

public class Main {
    public static void main(String[] args) {
        Car c = new Car();
        c.setHandDrive(HandDrive.RIGHT);

        SimpleModule module = new SimpleModule();
        module.addSerializer(HandDrive.class, new HardDriveSerializer());

        ObjectMapper objectMapper = new ObjectMapper();
        objectMapper.setSerializationInclusion(JsonInclude.Include.NON_NULL);
        objectMapper.registerModule(module);
        try {
            System.out.println(objectMapper.writeValueAsString(c));
        } catch (JsonProcessingException e) {
            e.printStackTrace();
        }

        XmlMapper xmlMapper = new XmlMapper();
        xmlMapper.registerModule(module);
        try {
            System.out.println(xmlMapper.writeValueAsString(c));
        } catch (JsonProcessingException e) {
            throw new RuntimeException(e);
        }
    }
}

enum HandDrive {
    RIGHT("right"),
    LEFT("left");

    private String value;

    HandDrive(String value) {
        this.value = value;
    }

    public String getValue() {
        return value;
    }
}



Custom Serializer Approach for Any Enum


In case you want to define a single custom serializer for any enum encountered during the marshalling process, you could make your custom serializer subtype 
Enum
, provide the name of a field to use as the serialization value, and then use reflection to retrieve the field's value. Here is a demo at 
OneCompiler
.


public class EnumSerializer extends StdSerializer<Enum> {

    private final String fieldName;

    public EnumSerializer(String fieldName) {
        this(null, fieldName);
    }

    public EnumSerializer(Class<Enum> t, String fieldName) {
        super(t);
        this.fieldName = fieldName;
    }

    @Override
    public void serialize(Enum value, JsonGenerator gen, SerializerProvider provider) throws IOException {
        try {
            Field field = value.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            gen.writeString(field.get(value).toString());
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException(e);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Car c = new Car();
        c.setHandDrive(HandDrive.RIGHT);
        c.setHandDrive2(HandDrive2.DOWN);

        SimpleModule module = new SimpleModule();
        module.addSerializer(HandDrive.class, new EnumSerializer("value"));
        module.addSerializer(HandDrive2.class, new EnumSerializer("otherValue"));

        ObjectMapper mapper = new ObjectMapper();
        mapper.setSerializationInclusion(JsonInclude.Include.NON_NULL);
        mapper.registerModule(module);
        try {
            System.out.println(mapper.writeValueAsString(c));
        } catch (JsonProcessingException e) {
            e.printStackTrace();
        }

        XmlMapper xmlMapper = new XmlMapper();
        xmlMapper.registerModule(module);
        try {
            System.out.println(xmlMapper.writeValueAsString(c));
        } catch (JsonProcessingException e) {
            throw new RuntimeException(e);
        }
    }
}

enum HandDrive {
    RIGHT("right"),
    LEFT("left");

    private String value;

    HandDrive(String value) {
        this.value = value;
    }

    public String getValue() {
        return value;
    }
}

enum HandDrive2 {
    UP("up"),
    DOWN("down");

    private String otherValue;

    HandDrive2(String otherValue) {
        this.otherValue = otherValue;
    }

    public String getOtherValue() {
        return otherValue;
    }
}

If I understand correctly you are struggling with managing multiple beans of the type 
RestClient
.
This is what the 
@Qualifier
 annotation is for:


    @Bean(name = "gold")
    @Qualifier("gold")
    RestClient restGoldClient(RestClient.Builder builder, OAuth2ClientHttpRequestInterceptor interceptor) {
        return ...
    }

    @Bean(name = "stock")
    @Qualifier("stock")
    RestClient restStockClient() {
        return ...
    }

    @Bean
    public GoldPriceHttpExchange goldPriceHttpExchange(@Qualifier("gold") RestClient restGoldClient) {
        return ...
    }


    @Bean
    public StockPriceHttpExchange stockPriceHttpExchange(@Qualifier("stock") RestClient restStockClient) {
        return ...
    }



The above will match up each 
RestClient
 parameter with the respective bean that has the corresponding 
@Qualifier
 annotation.


You can now have both HttpExchange types in your controller and switch between them using standard control flow:


@Autowired
GoldPriceHttpExchange goldPriceHttpExchange;

@Autowired
StockPriceHttpExchange stockPriceHttpExchange;

public String getSomePriceDependingOnConfiguration() {
    Map<String, String> priceResponse = 
        switch(someStringProperty) {
            case "gold"  -> goldPriceHttpExchange.getPrice();
            case "stock" -> stockPriceHttpExchange.getPrice();
            default -> null;
        }
    }
    if(priceResponse == null) {
        throw new IllegalArgumentException("Ivalid value for someStringProperty: "+ someStringProperty);
    }
    //else
    return priceResponse.get("price");
}



'someStringProperty' is just an example. How you determine which price to obtain is up to you.


For more information about the 
@Qualifier
 annotation, please see 
https://docs.spring.io/spring-framework/reference/core/beans/annotation-config/autowired-qualifiers.html

In Java, the factorial of a number n is the product of all positive integers less than or equal to n. By definition, 0! is equal to 1, even though it may seem like an exception.


In the original Java code, factorials were calculated only for n > 0, so 0! was skipped. However, the calcFactorial() method already correctly handles 0! because when n = 0, the for loop doesn't run, and the initial value fact = 1 remains unchanged.


To fix this, we just need to change the condition in the main() method from if(n > 0) to if(n >= 0) so that 0 is included.


Here's the code:


import java.util.*;
public class main {

  public static int calcFactorial(int n) {
     int fact = 1;
     for (int i = 1; i <= n; i++) {
         fact = fact * i;
     }
     return fact;
  }

  public static void main(String[] args) {
      Scanner sc = new Scanner(System.in);
      System.out.print("Enter the number : ");
      int n = sc.nextInt();

      if(n >= 0) {
        int factorial = calcFactorial(n);
        System.out.println("Factorial = " + factorial);
      }
      else {
        System.out.println("Factorial for negative numbers do not exist!");
      }
  }
}



Now, this code correctly calculates 0! = 1 and handles all non-negative integers properly.

