I think you shoud be able to solve the issue with a ViewModel.


The problem is, as you have already guessed, that you're trying to modify a View that it's already been destroyed with the Activity lifecycle on the rotation event, so anything that you store or refer in that Activity gets destroyed too (also the runOnUiThread method).


A ViewModel on the other hand has a lifetime on it's own, it survives the onDestroy event (if it's not the one triggered by onFinish), the point is to store every data in the ViewModel and to make every View point to it.

I've tried this simple following code and it's working fine:


public class MainActivity extends AppCompatActivity {
    private MyViewModel viewmodel;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        viewmodel = new ViewModelProvider(this).get(MyViewModel.class);

        EditText editText = findViewById(R.id.editTextText);

        //the text is set only with the value of the viewmodel
        viewmodel.mutableText.observe(this, textValue -> {
            if (!editText.getText().toString().equals(textValue))
                editText.setText(textValue);
        });

        editText.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

            @Override
            public void onTextChanged(CharSequence newText, int start, int before, int count) {
                //storing the written text in the viewmodel
                viewmodel.mutableText.setValue(newText.toString());
            }

            @Override
            public void afterTextChanged(Editable s) {}
        });

        Button button = findViewById(R.id.login);
        button.setOnClickListener(v -> showBiometricPrompt());
    }


    public void showBiometricPrompt() {
        Executor executor = ContextCompat.getMainExecutor(this);

        BiometricPrompt biometricPrompt = new BiometricPrompt(this, executor, new BiometricPrompt.AuthenticationCallback() {
            @Override
            public void onAuthenticationSucceeded(@NonNull BiometricPrompt.AuthenticationResult result) {
                super.onAuthenticationSucceeded(result);
                //calling the method in the view model, it will update the text that consequently will be pushed onto the observer
                viewmodel.onAuthenticationSuccess();
            }

            @Override
            public void onAuthenticationError(int errorCode, @NonNull CharSequence errString) {
                super.onAuthenticationError(errorCode, errString);
                //same
                viewmodel.onAuthenticationError(errString);
            }
        });

        BiometricPrompt.PromptInfo promptInfo = new BiometricPrompt.PromptInfo.Builder()
            .setTitle("Android is complicated!")
            .setNegativeButtonText("Cancel")
            .build();

        biometricPrompt.authenticate(promptInfo);
    }
}



public class MyViewModel extends ViewModel {

    MutableLiveData<String> mutableText = new MutableLiveData<>("");

    public void onAuthenticationError(CharSequence errString) {
        mutableText.setValue(errString.toString()); // error message
    }

    public void onAuthenticationSuccess() {
        mutableText.setValue("Success");
    }
}



