@Data
@SuperBuilder
@NoArgsConstructor
@AllArgsConstructor
@Table(uniqueConstraints = {@UniqueConstraint(columnNames = {"academy_id", "email"})})
public class AcademyUser extends EntityBase {

  @EmbeddedId 
  private AcademyUserKey key;

  @ManyToOne
  @MapsId("academyId")
  @JoinColumn(name = "academy_id")
