We can look at the 
source
 of the getter and setter of 
dragDropMode
 property:


void QAbstractItemView::setDragDropMode(DragDropMode behavior)
{
    Q_D(QAbstractItemView);
    d->dragDropMode = behavior;
    setDragEnabled(behavior == DragOnly || behavior == DragDrop || behavior == InternalMove);
    setAcceptDrops(behavior == DropOnly || behavior == DragDrop || behavior == InternalMove);
}

QAbstractItemView::DragDropMode QAbstractItemView::dragDropMode() const
{
    Q_D(const QAbstractItemView);
    DragDropMode setBehavior = d->dragDropMode;
    if (!dragEnabled() && !acceptDrops())
        return NoDragDrop;

    if (dragEnabled() && !acceptDrops())
        return DragOnly;

    if (!dragEnabled() && acceptDrops())
        return DropOnly;

    if (dragEnabled() && acceptDrops()) {
        if (setBehavior == InternalMove)
            return setBehavior;
        else
            return DragDrop;
    }

    return NoDragDrop;
}



As you can see, the setter indeed itself uses 
setDragEnabled
 and 
setAcceptDrops
 to set corresponding properties, which corresponds to behaviour you noticed. The only additional thing it does is setting underlying 
d->dragDropMode
 (
d
 appears via 
Q_D
 macro and is used to implement private data, see 
this question
), but the getter doesn't even consider its value except when 
dragEnabled() && acceptDrops()
, for which case, as you observed, the saved member differentiates between move and copy behaviour. By default it is set to 
QAbstractItemView::NoDragDrop
 (see 
here
), so the getter returns 
DragDrop
