Another option is to create a 
JTable
 that contains a 
File
 copy of every data column.
This way, you would need to change the 
TableCellRenderer
 to display the file type, file name, or file creation date from the 
File
 depending on the column,
but the comparators for each column would be able to get the file type and file creation date from the 
File
 at the same time.


import java.awt.*;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.attribute.BasicFileAttributes;
import java.nio.file.attribute.FileTime;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import javax.swing.*;
import javax.swing.table.DefaultTableCellRenderer;
import javax.swing.table.DefaultTableModel;
import javax.swing.table.TableModel;
import javax.swing.table.TableRowSorter;

public class GroupDirectoriesFirstComparatorTest {
  private Component makeUI() {
    String[] columnNames = {"Type", "Filename", "Date"};
    DefaultTableModel model = new DefaultTableModel(columnNames, 0) {
      @Override
      public Class<?> getColumnClass(int column) {
        return File.class;
      }
    };
    JTable table = new JTable(model);
    table.setAutoCreateRowSorter(true);
    table.setDefaultRenderer(File.class, new FileCellRenderer());
    RowSorter<? extends TableModel> sorter = table.getRowSorter();
    if (sorter instanceof TableRowSorter) {
      TableRowSorter<? extends TableModel> rs =
          (TableRowSorter<? extends TableModel>) sorter;
      for (int i = 0; i < model.getColumnCount(); i++) {
        rs.setComparator(i, new GroupDirectoriesFirstComparator(table, i));
      }
    }
    JButton button = new JButton("Choose directory");
    button.addActionListener(e -> {
      JFileChooser chooser = new JFileChooser();
      chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
      int ret = chooser.showOpenDialog(button.getRootPane());
      if (ret == JFileChooser.APPROVE_OPTION) {
        model.setRowCount(0);
        File[] files = chooser.getSelectedFile().listFiles();
        if (files != null) {
          Arrays.stream(files)
              .map(f -> Collections.nCopies(3, f).toArray())
              .forEach(model::addRow);
        }
      }
    });
    JPanel p = new JPanel(new BorderLayout());
    p.add(new JScrollPane(table));
    p.add(button, BorderLayout.SOUTH);
    return p;
  }

  public static void main(String[] args) {
    EventQueue.invokeLater(() -> {
      JFrame frame = new JFrame();
      frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
      frame.getContentPane().add(
          new GroupDirectoriesFirstComparatorTest().makeUI());
      frame.pack();
      frame.setLocationRelativeTo(null);
      frame.setVisible(true);
    });
  }
}

class FileCellRenderer extends DefaultTableCellRenderer {
  private final DateFormat dateFormat = new SimpleDateFormat("yyyy.MM.dd");

  @Override
  public Component getTableCellRendererComponent(
      JTable table, Object value,
      boolean isSelected, boolean hasFocus,
      int row, int column) {
    Component c = super.getTableCellRendererComponent(
        table, value, isSelected, hasFocus, row, column);
    if (c instanceof JLabel && value instanceof File) {
      JLabel l = (JLabel) c;
      l.setHorizontalAlignment(LEFT);
      File file = (File) value;
      switch (table.convertColumnIndexToModel(column)) {
        case 0:
          l.setText(file.isDirectory() ? "DIRECTORY" : "FILE");
          break;
        case 1:
          l.setText(file.getName());
          break;
        case 2:
          l.setHorizontalAlignment(RIGHT);
          try {
            BasicFileAttributes attr =
                Files.readAttributes(file.toPath(), BasicFileAttributes.class);
            l.setText(dateFormat.format(attr.creationTime().toMillis()));
          } catch (IOException e) {
            throw new RuntimeException(e);
          }
          break;
        default:
          break;
      }
    }
    return c;
  }
}

class FileComparator implements Comparator<File> {
  private final int column;

  public FileComparator(int column) {
    this.column = column;
  }

  @Override
  public int compare(File a, File b) {
    switch (column) {
      case 0: return getWeight(a) - getWeight(b);
      case 2: return Long.compare(getCreationTime(a), getCreationTime(b));
      default: return a.getName().compareToIgnoreCase(b.getName());
    }
  }

  public int getColumn() {
    return column;
  }

  public static int getWeight(File file) {
    return file.isDirectory() ? 1 : 2;
  }

  public static Long getCreationTime(File file) {
    BasicFileAttributes attr;
    try {
      attr = Files.readAttributes(file.toPath(), BasicFileAttributes.class);
    } catch (IOException e) {
      throw new RuntimeException(e);
    }
    return Optional.ofNullable(attr)
        .map(BasicFileAttributes::creationTime)
        .map(FileTime::toMillis)
        .orElse(0L);
  }
}

// https://java-swing-tips.blogspot.com/2011/11/jtable-group-directories-first-sorting.html
class GroupDirectoriesFirstComparator extends FileComparator {
  private final JTable table;

  public GroupDirectoriesFirstComparator(JTable table, int column) {
    super(column);
    this.table = table;
  }

  @Override
  public int compare(File a, File b) {
    int v = getWeight(a) - getWeight(b);
    return v == 0 ? super.compare(a, b) : v * getSortOrderDirection();
  }

  private int getSortOrderDirection() {
    int dir = 1;
    List<? extends RowSorter.SortKey> keys = table.getRowSorter().getSortKeys();
    if (!keys.isEmpty()) {
      RowSorter.SortKey sortKey = keys.get(0);
      if (sortKey.getColumn() == getColumn() &&
          sortKey.getSortOrder() == SortOrder.DESCENDING) {
        dir = -1;
      }
    }
    return dir;
  }
}

One way I can think of, is to check if the mouse position is in correct layout bounds of the node, to evaluate and proceed with mouse event handlers. Something like


testLabel.getLayoutBounds().contains(event.getX(), event.getY());



Below is a refactored demo of your demo. You can notice the right label is default label and the left one is the one with padding. Once I add for the valid position check, I can only trigger my desired actions in the mouse event handlers (i.e to highlight the label with yellow background).


Note: I think this can be even simplified to do the check directly in the custom event dispatcher rather than doing in each handler.






import javafx.application.Application;
import javafx.scene.Node;
import javafx.scene.Scene;
import javafx.scene.control.Label;
import javafx.scene.input.MouseEvent;
import javafx.scene.layout.HBox;
import javafx.scene.text.TextAlignment;
import javafx.stage.Stage;


public class ClickableLabelRegion_Demo extends Application {

    private final static String CSS = "data:text/css," +
            """
                                    .test-label1 {
                                        -fx-background-color: blue;
                                        -fx-border-color: red;
                                        -fx-font-family: "Harlow Solid Italic";
                                        -fx-font-size: 100;
                                        -fx-padding: -40 20 0 20;
                                    }

                                    .test-label2 {
                                        -fx-background-color: blue;
                                        -fx-border-color: red;
                                        -fx-font-family: "Harlow Solid Italic";
                                        -fx-font-size: 100;
                                    }

                                    .test-bg {
                                        -fx-background-color: yellow;
                                    }
                    """;

    @Override
    public void start(Stage stage) {
        HBox root = new HBox();
        root.setStyle("-fx-background-color: black;-fx-padding:40px;-fx-spacing:50px;");
        root.getChildren().addAll(createTestLabel(1), createTestLabel(2));
        Scene scene = new Scene(root, 1150, 450);
        scene.getStylesheets().add(CSS);
        stage.setScene(scene);
        stage.setTitle("Clickable Label Region Demo");
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }

    private Label createTestLabel(int i) {
        Label testLabel = new Label("Placeholder\nText");
        testLabel.getStyleClass().add("test-label" + i);
        testLabel.setTextAlignment(TextAlignment.CENTER);
        testLabel.setOnMouseEntered(event -> mouseEntered(testLabel, event, i));
        testLabel.setOnMouseMoved(event -> mouseMoved(testLabel, event, i));
        testLabel.setOnMouseExited(event -> mouseExited(testLabel, event, i));
        testLabel.setOnMousePressed(event -> mousePressed(testLabel, event, i));
        testLabel.setOnMouseReleased(event -> mouseReleased(testLabel, event, i));
        testLabel.setOnMouseClicked(event -> mouseClicked(testLabel, event, i));
        return testLabel;
    }

    private boolean isValidRegion(Node n, MouseEvent e) {
        return n.getLayoutBounds().contains(e.getX(), e.getY());
    }

    private void mouseClicked(Node n, MouseEvent e, int i) {
        if (isValidRegion(n, e)) {
            System.out.println("Mouse clicked " + i);
        }
    }

    private void mousePressed(Node n, MouseEvent e, int i) {
        if (isValidRegion(n, e)) {
            System.out.println("Mouse pressed " + i);
            n.getStyleClass().add("test-bg");
        }
    }

    private void mouseReleased(Node n, MouseEvent e, int i) {
        if (isValidRegion(n, e)) {
            System.out.println("Mouse released " + i);
            n.getStyleClass().remove("test-bg");
        }
    }

    private void mouseEntered(Node n, MouseEvent e, int i) {
        if (isValidRegion(n, e)) {
            System.out.println("Mouse entered " + i);
        }
    }

    private void mouseMoved(Node n, MouseEvent e, int i) {
        if (isValidRegion(n, e)) {
            System.out.println("Mouse moved " + i);
        }
    }

    private void mouseExited(Node n, MouseEvent e, int i) {
        System.out.println("Mouse exited " + i);
    }
}



UPDATE (using clip):


As mentioned by @jewelsea, applying a clip on the Label resolves the issue.


class CustomLabel extends Label {
    public CustomLabel(String text) {
        super(text);
        Rectangle clip = new Rectangle();
        setClip(clip);
        layoutBoundsProperty().addListener(p -> {
            Bounds b = getLayoutBounds();
            clip.setWidth(b.getWidth());
            clip.setHeight(b.getHeight());
        });
    }
}

This is a common point of confusion with Spring Data Couchbase. The issue is that 
Spring Data Couchbase
 doesn't use Jackson for entity mapping - it uses its own 
MappingCouchbaseConverter
 which is part of Spring Data's mapping infrastructure.


So while @JsonAnySetter/@JsonAnyGetter work perfectly with ObjectMapper, they're simply ignored by Spring Data Couchbase's converter.


MappingCouchbaseConverter


Yo can use custom converter like:


@ReadingConverter
public class AssetReadConverter implements Converter<CouchbaseDocument, Asset> {
    @Override
    public Asset convert(CouchbaseDocument source) {
        Map<String, Object> content = new HashMap<>(source.getContent());
        Asset asset = new Asset();
        asset.setId(source.getId());
        asset.setType((String) content.remove("type"));
        content.remove("_class");
        asset.setProperties(content);
        return asset;
    }
}

@WritingConverter  
public class AssetWriteConverter implements Converter<Asset, CouchbaseDocument> {
    @Override
    public CouchbaseDocument convert(Asset source) {
        CouchbaseDocument doc = new CouchbaseDocument(source.getId());
        doc.put("type", source.getType());
        source.getProperties().forEach(doc::put);
        return doc;
    }
}

@Override
public CouchbaseCustomConversions customConversions() {
    return new CouchbaseCustomConversions(List.of(new AssetReadConverter(), new AssetWriteConverter()));
}

