you need to 
carry the
 path through each recursive call rather than mutating a shared list.


To pass a new list each time u descend:


def search(obj, target, path=None):
    path = [] if path is None else path
    results = []

    if isinstance(obj, dict):
        for k, v in obj.items():
            results += search(v, target, path + [k])
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results += search(v, target, path + [i])
    else:
        if target in obj:
            results.append(path + [obj])

    return results

def test_search(data, hint, expected_result):
    for expected, actual in zip(expected_result, search(data, hint)):
        assert expected == actual

