class HeapQuiz {
    int id = 0;
    public static void main(String[] args) {
        int x = 0;
        HeapQuiz[] hq = new HeapQuiz[5]; // Creates an array with 5 slots (all null initially)

        while (x < 3) { // Runs from 0 to 2
            hq[x] = new HeapQuiz(); // Creates a new object for hq[0], hq[1], and hq[2]
            hq[x].id = x; // Assigns the id value
