  val testExtensions by registering(Test::class) {
    useJUnitPlatform {
      includeTags("extension-test")
    }

    val test by sourceSets
    classpath = test.runtimeClasspath
    testClassesDirs = test.output.classesDirs

    // Enable console logging to show output in Stack Overflow answer; not
    // needed in a real project.
    testLogging {
      events("passed", "skipped", "failed")
    }
  }

  // Configure 'test' task to exclude tests for extensions. It will otherwise
  // function as normal.
  test {
    // Doesn't require testing extensions, but should run those tests first if
    // both tasks are requested.
    mustRunAfter(testExtensions)
    useJUnitPlatform {
      excludeTags("extension-test", "testkit-test")
    }
  }

  check {
    // Include testing extensions when running full check.
    dependsOn(testExtensions)
  }
}




