MockSwingTests.java


package com.example;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.util.List;
import javax.swing.SwingUtilities;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.DynamicNode;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

@Tag("testkit-test")
@ExtendWith(EdtExtension.class)
@DisplayName("Test EdtExtension")
public class MockSwingTests {

  private boolean setupGuiCalled;

  @SwingSetup
  void setupGui() {
    assertTrue(SwingUtilities.isEventDispatchThread(), "isEventDispatchThread");
    assertFalse(setupGuiCalled, "setupGui called previously");
    setupGuiCalled = true;
  }

  @Test
  @DisplayName("with @Test method")
  void test() {
    assertTrue(SwingUtilities.isEventDispatchThread(), "isEventDispatchThread");
    assertTrue(setupGuiCalled, "setupGui was not called before test");
  }

  @TestFactory
  List<DynamicNode> dynamicTest() {
    assertFalse(SwingUtilities.isEventDispatchThread(), "isEventDispatchThread");
    assertTrue(setupGuiCalled, "setupGuiCalled before dynamic test creation");
    return List.of(DynamicTest.dynamicTest("with DynamicTest", () -> {
      assertTrue(SwingUtilities.isEventDispatchThread(), "isEventDispatchThread");
    }));
  }

  @ParameterizedTest(name = "with @ParameterizedTest")
  @ValueSource(strings = "foo")
  void templateTest(String param) {
    assertTrue(SwingUtilities.isEventDispatchThread(), "isEventDispatchThread");
    assertTrue(setupGuiCalled, "setupGui was not called before test");
  }

  @Test
  @DisplayName("with failing test (FAILURE EXPECTED)")
  void failingTest() {
    fail("This should fail the test");
  }
}



Extension Tests


EdtExtensionTests.java


package com.example;

import static org.junit.platform.engine.discovery.DiscoverySelectors.selectClass;
import static org.junit.platform.testkit.engine.EventConditions.event;
import static org.junit.platform.testkit.engine.EventConditions.finishedSuccessfully;
import static org.junit.platform.testkit.engine.EventConditions.finishedWithFailure;
import static org.junit.platform.testkit.engine.EventConditions.test;

import java.util.function.Predicate;
import org.assertj.core.api.Condition;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.TestInstance.Lifecycle;
import org.junit.platform.testkit.engine.EngineExecutionResults;
import org.junit.platform.testkit.engine.EngineTestKit;
import org.junit.platform.testkit.engine.Events;
import org.opentest4j.AssertionFailedError;

@Tag("extension-test")
@TestInstance(Lifecycle.PER_CLASS)
@DisplayName("Test MockSwingTests")
class EdtExtensionTests {

  EngineExecutionResults results;
  Events testEvents;

  @BeforeAll
  void executeTests() {
    results = EngineTestKit.engine("junit-jupiter")
        .selectors(selectClass(MockSwingTests.class))
        .execute();
    testEvents = results.testEvents();
  }

  @Test
  @DisplayName("had 3 successful tests and 1 failed test")
  void verifyStatistics() {
    testEvents.assertStatistics(stats -> stats.succeeded(3).failed(1));
  }

  @Test
  @DisplayName("had test() succeed")
  void verifyTest() {
    var uniqueIdSubstring = "method:test()";
    testEvents
        .assertThatEvents()
        .haveExactly(1, event(test(uniqueIdSubstring), finishedSuccessfully()));
  }

  @Test
  @DisplayName("had dynamicTest() succeed")
  void verifyDynamicTest() {
    var uniqueIdSubstring = "test-factory:dynamicTest()";
    testEvents
        .assertThatEvents()
        .haveExactly(1, event(test(uniqueIdSubstring), finishedSuccessfully()));
  }

  @Test
  @DisplayName("had templateTest(String) succeed")
  void verifyTemplateTest() {
    var uniqueIdSubstring = "test-template:templateTest(java.lang.String)";
    testEvents
        .assertThatEvents()
        .haveExactly(1, event(test(uniqueIdSubstring), finishedSuccessfully()));
  }

  @Test
  @DisplayName("had failingTest() fail")
  void verifyFailingTest() {
    var uniqueIdSubstring = "method:failingTest()";
    testEvents
        .assertThatEvents()
        .haveExactly(1, event(test(uniqueIdSubstring), finishedWithFailure(unwrappedError())));
  }

  private Condition<Throwable> unwrappedError() {
    Predicate<Throwable> predicate = th -> th instanceof AssertionFailedError;
    String description = "unwrapped test failure from InvocationTargetException";
    return new Condition<>(predicate, description);
  }
}




