Here is ready to use method that convert list to multi map.


    public static <T, K, V> MultiValuedMap<K, V> toMultiMap(
            Function<T, K> keyMapping,
            Function<T, V> valueMapping,
            List<T> list) {
        MultiValuedMap<K, V> m = new MultiValuedMap<>();
        list.stream()
                .collect(Collectors.groupingBy(
                        keyMapping,
                        Collectors.mapping(valueMapping,
                                Collectors.toList())))
                .forEach(m::putAll);
        return m;
    }

