The size of the stack pane is determined by its content; the content is the image 
view
 and the canvas. Both of those have size determined by the values you pass to 
fitWidth
 and 
fitHeight
. So the content of the node you are snapshotting is determined by those values. Any additional space in the image you use for snapshotting will just be empty.


If I understand the requirements correctly, you want to create an image on disk that contains the original image, at its original size, along with the "annotations" from the canvas. Note that to do this, you will need to somehow scale the annotations to be the same size as the original image.


One approach is:




Snapshot the canvas to an image.


Create an image view to hold the image of the canvas.


Set the 
fitWidth
 and 
fitHeight
 of that image view to be the size of the original image.



This will scale the snapshot of the canvas to be the same size as the original image.






Create another 
ImageView
 to display the original image at its original (i.e. default) size.


Create a new stack pane to hold the two image views.


Snapshot the new stack pane.




    private void saveSnapshot(Image image, Canvas annotations) {
        SnapshotParameters params = new SnapshotParameters();
        params.setFill(Color.TRANSPARENT);

        Image canvasImage = annotations.snapshot(params, null);
        ImageView annotationsView = new ImageView(canvasImage);
        annotationsView.setFitWidth(image.getWidth());
        annotationsView.setFitHeight(image.getHeight());

        ImageView imageView = new ImageView(image);

        StackPane stack = new StackPane(imageView, annotationsView);
        stack.setStyle("-fx-background-color: transparent;");

        Scene scene = new Scene(stack);

        Image snapshot = stack.snapshot(params, null);

        BufferedImage bufferedImage = SwingFXUtils.fromFXImage(snapshot, null);
        File outFile = new File("500.png");

        try {
            ImageIO.write(bufferedImage, "png", outFile);
            System.out.println("Saved to: " + outFile.getAbsolutePath());
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }



Here is a complete working example with this approach:


import javafx.application.Application;
import javafx.beans.binding.Bindings;
import javafx.beans.binding.DoubleBinding;
import javafx.embed.swing.SwingFXUtils;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.SnapshotParameters;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.control.Button;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.input.MouseButton;
import javafx.scene.layout.StackPane;
import javafx.scene.layout.VBox;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.Objects;

public class DrawOverImageCanvas extends Application {
    private double lastX;
    private double lastY;

    @Override
    public void start(Stage stage) {
        Image image = new Image(Objects.requireNonNull(getClass().getResourceAsStream("yourPath")));


        if (image.isError())
            System.err.println("Could not load image: " + image.getException());

        ImageView imageView = new ImageView(image);
        imageView.setPreserveRatio(true);
        imageView.setSmooth(true);
        imageView.setFitWidth(500);

        Canvas canvas = new Canvas();
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.setLineWidth(3);
        gc.setStroke(Color.RED);

        canvas.setOnMousePressed(e -> {
            if (e.getButton() == MouseButton.PRIMARY) {
                lastX = e.getX();
                lastY = e.getY();
            }
        });

        canvas.setOnMouseDragged(e -> {
            if (e.getButton() == MouseButton.PRIMARY) {
                double x = e.getX();
                double y = e.getY();
                gc.strokeLine(lastX, lastY, x, y);
                lastX = x;
                lastY = y;
            }
        });

        StackPane stack = new StackPane(imageView, canvas);
        stack.setAlignment(Pos.CENTER);
        stack.setStyle("-fx-background-color: transparent;");

        DoubleBinding imageWidth = Bindings.createDoubleBinding(
                () -> imageView.getLayoutBounds().getWidth(),
                imageView.layoutBoundsProperty()
        );

        DoubleBinding imageHeight = Bindings.createDoubleBinding(
                () -> imageView.getLayoutBounds().getHeight(),
                imageView.layoutBoundsProperty()
        );

        stack.minWidthProperty().bind(imageWidth);
        stack.prefWidthProperty().bind(imageWidth);
        stack.maxWidthProperty().bind(imageWidth);

        stack.minHeightProperty().bind(imageHeight);
        stack.prefHeightProperty().bind(imageHeight);
        stack.maxHeightProperty().bind(imageHeight);

        canvas.widthProperty().bind(imageWidth);
        canvas.heightProperty().bind(imageHeight);

        Button saveButton = new Button("Save PNG");
        saveButton.setOnAction(e -> saveSnapshot(image, canvas));

        Button clearButton = new Button("Clear Drawing");
        clearButton.setOnAction(e -> {
            gc.clearRect(0, 0, canvas.getWidth(), canvas.getHeight());
        });

        VBox root = new VBox(10, stack, new VBox(5, saveButton, clearButton));
        root.setAlignment(Pos.CENTER);
        root.setStyle("-fx-padding: 10; -fx-background-color: #333333;");

        Scene scene = new Scene(root);
        stage.setTitle("Draw over Image with Canvas");
        stage.setScene(scene);
        stage.sizeToScene();
        stage.show();
    }

    private void saveSnapshot(Image image, Canvas annotations) {
        SnapshotParameters params = new SnapshotParameters();
        params.setFill(Color.TRANSPARENT);

        Image canvasImage = annotations.snapshot(params, null);
        ImageView annotationsView = new ImageView(canvasImage);
        annotationsView.setFitWidth(image.getWidth());
        annotationsView.setFitHeight(image.getHeight());

        ImageView imageView = new ImageView(image);

        StackPane stack = new StackPane(imageView, annotationsView);
        stack.setStyle("-fx-background-color: transparent;");

        Scene scene = new Scene(stack);

        Image snapshot = stack.snapshot(params, null);

        BufferedImage bufferedImage = SwingFXUtils.fromFXImage(snapshot, null);
        File outFile = new File("500.png");

        try {
            ImageIO.write(bufferedImage, "png", outFile);
            System.out.println("Saved to: " + outFile.getAbsolutePath());
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }
}



Note that if the canvas is upscaled a large amount, the quality may not be ideal. In particular, the width of lines will be scaled by the same amount as the scaling between the original image and the image view in the application. (Similarly if you were to add points, the radius of the points would be scaled, etc.) So in this implementation, the line width is 3 units 
in the coordinate system of the image view in the application
. Using an 
ImageView
 to perform the scaling at least gives you control over the smoothing etc. to a small extent.


A more complex approach would be to either track all the lines drawn on the canvas (or perhaps to retrieve them from the existing canvas) and recreate those on a new canvas with appropriately transformed coordinates. Whether or not this additional effort is worthwhile depends a lot on your use case.


Here is a rudimentary implementation of this second idea. This just assumes all "annotations" are drawn as lines; you may need something more complicated in the real application. In this implementation, the line width ends up being 3 pixels 
in the coordinate system of the image you write to disk
.


import javafx.application.Application;
import javafx.beans.binding.Bindings;
import javafx.beans.binding.DoubleBinding;
import javafx.embed.swing.SwingFXUtils;
import javafx.geometry.Point2D;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.SnapshotParameters;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.control.Button;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.input.MouseButton;
import javafx.scene.layout.StackPane;
import javafx.scene.layout.VBox;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public class DrawOverImageCanvas extends Application {

    @Override
    public void start(Stage stage) {
        Image image = new Image(Objects.requireNonNull(getClass().getResourceAsStream("yourPath")));


        if (image.isError())
            System.err.println("Could not load image: " + image.getException());

        ImageView imageView = new ImageView(image);
        imageView.setPreserveRatio(true);
        imageView.setSmooth(true);
        imageView.setFitWidth(500);

        Canvas canvas = createCanvas();
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.setLineWidth(3); 

        List<Point2D> points = new ArrayList<>();

        canvas.setOnMousePressed(e -> {
            if (e.getButton() == MouseButton.PRIMARY) {
                points.add(new Point2D(e.getX(), e.getY()));
            }
        });

        canvas.setOnMouseDragged(e -> {
            if (e.getButton() == MouseButton.PRIMARY) {
                double x = e.getX();
                double y = e.getY();
                Point2D lastPoint = points.getLast();
                gc.strokeLine(lastPoint.getX(), lastPoint.getY(), x, y);
                points.add(new Point2D(x, y));
            }
        });

        StackPane stack = new StackPane(imageView, canvas);
        stack.setAlignment(Pos.CENTER);
        stack.setStyle("-fx-background-color: transparent;");

        DoubleBinding imageWidth = Bindings.createDoubleBinding(
                () -> imageView.getLayoutBounds().getWidth(),
                imageView.layoutBoundsProperty()
        );

        DoubleBinding imageHeight = Bindings.createDoubleBinding(
                () -> imageView.getLayoutBounds().getHeight(),
                imageView.layoutBoundsProperty()
        );

        stack.minWidthProperty().bind(imageWidth);
        stack.prefWidthProperty().bind(imageWidth);
        stack.maxWidthProperty().bind(imageWidth);

        stack.minHeightProperty().bind(imageHeight);
        stack.prefHeightProperty().bind(imageHeight);
        stack.maxHeightProperty().bind(imageHeight);

        canvas.widthProperty().bind(imageWidth);
        canvas.heightProperty().bind(imageHeight);

        Button saveButton = new Button("Save PNG");
        saveButton.setOnAction(e -> saveSnapshot(image, points, image.getWidth() / canvas.getWidth(), image.getHeight() / canvas.getHeight()));

        Button clearButton = new Button("Clear Drawing");
        clearButton.setOnAction(e -> {
            gc.clearRect(0, 0, canvas.getWidth(), canvas.getHeight());
            points.clear();
        });

        VBox root = new VBox(10, stack, new VBox(5, saveButton, clearButton));
        root.setAlignment(Pos.CENTER);
        root.setStyle("-fx-padding: 10; -fx-background-color: #333333;");

        Scene scene = new Scene(root);
        stage.setTitle("Draw over Image with Canvas");
        stage.setScene(scene);
        stage.sizeToScene();
        stage.show();
    }

    private Canvas createCanvas() {
        Canvas canvas = new Canvas();
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.setStroke(Color.RED);
        return canvas;
    }

    private void saveSnapshot(Image image, List<Point2D> points, double scaleX, double scaleY) {

        SnapshotParameters params = new SnapshotParameters();
        params.setFill(Color.TRANSPARENT);

        Canvas canvas = createCanvas();
        canvas.setWidth(image.getWidth());
        canvas.setHeight(image.getHeight());
        GraphicsContext gc = canvas.getGraphicsContext2D();

        gc.setLineWidth(3); // customize as needed

        for (int i = 1 ; i < points.size(); i++) {
            Point2D first = points.get(i-1);
            Point2D second = points.get(i);

            gc.strokeLine(first.getX() * scaleX, first.getY() * scaleY, second.getX() * scaleX, second.getY() * scaleY);
        }

        ImageView imageView = new ImageView(image);

        StackPane stack = new StackPane(imageView, canvas);
        stack.setStyle("-fx-background-color: transparent;");

        Scene scene = new Scene(stack);

        Image snapshot = stack.snapshot(params, null);

        BufferedImage bufferedImage = SwingFXUtils.fromFXImage(snapshot, null);
        File outFile = new File("500.png");

        try {
            ImageIO.write(bufferedImage, "png", outFile);
            System.out.println("Saved to: " + outFile.getAbsolutePath());
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }
}

